common:
vec3 aces(vec3 x){
return clamp((x*(2.51*x+.03))/(x*(2.43*x+.59)+.14),0.,1.);
}
float bayer4(vec2 px){
int x=int(mod(px.x,4.));
int y=int(mod(px.y,4.));
int i=x+y*4;
const int m[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5);
return(float(m[i])+.5)/16.;
}
float easeOutCubic(float x){
float f=1.-x;
return 1.-f*f*f;
}
float hash11(float p){
uint x=floatBitsToUint(p);
x=((x>>16u)^x)*2146503469u;
x=((x>>16u)^x)*2146503469u;
x=(x>>16u)^x;
return float(x>>8u)*(1./16777216.);
}
vec2 pixUV(vec2 fragCoord,vec2 res){
return(floor(fragCoord)+.5)/res;
}
vec3 retroQuantize(vec3 col,const vec3 pal[16],int n,vec2 px){
float d=bayer4(px)-.5;
vec3 c=col+d*(1./float(n));
int best=0;
float bd=1e9;
for(int i=0;i<16;i++){
if(i>=n)break;
vec3 diff=c-pal[i];
float dd=dot(diff,diff);
if(dd<bd){bd=dd;best=i;}
}
return pal[best];
}
vec3 toSRGB(vec3 c){
return mix(1.055*pow(c,vec3(1./2.4))-.055,c*12.92,step(c,vec3(.0031308)));
}
vec3 vignette(vec3 c,vec2 uv,float strength){
float d=distance(uv,vec2(.5));
return c*(1.-strength*smoothstep(.35,.85,d));
}
float wrapTime(float t,float period){
return t-period*floor(t/period);
}
vec3 retroFinalize(vec3 col,vec2 uv,vec2 fragCoord,const vec3 pal[16],int n){
vec3 q=retroQuantize(clamp(col,0.,1.),pal,n,fragCoord);
float d=distance(uv,vec2(.5));
return q*(1.-.25*smoothstep(.45,.9,d));
}
const vec3 PALETTE[16]=vec3[16](
vec3(.063,.063,.078),
vec3(.078,.204,.231),
vec3(.18,.18,.22),
vec3(.949,.918,.827),
vec3(.949,.651,.702),
vec3(.11,.29,.32),
vec3(.16,.4,.43),
vec3(.22,.51,.54),
vec3(.09,.14,.16),
vec3(.13,.13,.16),
vec3(.24,.24,.29),
vec3(.85,.8,.69),
vec3(.76,.5,.56),
vec3(.98,.96,.9),
vec3(.98,.85,.88),
vec3(.055,.055,.066)
);
const int PALETTE_N=16;
vec3 finalize(vec3 col,vec2 uv){
#ifdef PROFILE_RETRO
return retroFinalize(col,uv,gl_FragCoord.xy,PALETTE,PALETTE_N);
#else
col=aces(col);
col=vignette(col,uv,.25);
return toSRGB(col);
#endif
}
const int BC_EAR=1;
const int BC_BLINK=2;
const int BC_AIR=4;
const int BC_HEAD[11]=int[11](2,4,5,5,5,5,5,5,5,4,3);
int bigCatFill(ivec2 c,int k,int tail,int hip,ivec2 look,int headUp,int flags){
int id=0;
ivec2 b=c-ivec2(hip,0);
int bodyTop=6-k;
int bodyHalf=6+k/2;
if(b.x>=bodyHalf+1&&b.x<=bodyHalf+6){
int i=b.x-bodyHalf-1;
if(b.y==3-k+i/2+tail)id=2;
}
if(b.y>=0&&b.y<=bodyTop){
int hw=bodyHalf-max(0,b.y-2)/2;
if(abs(b.x)<=hw)id=(abs(b.x)==hw&&(b.y==0||b.y==bodyTop))?0:2;
}
if(abs(b.x)<=3&&b.y>=0&&b.y<=3-k)id=(b.y==0&&b.x==0)?1:3;
if((flags&BC_AIR)!=0&&b.y==-1&&(abs(b.x)==2||abs(b.x)==3))id=2;
int hy=11-2*k+headUp;
int dy=c.y-hy;
if(dy>=-5&&dy<=5&&abs(c.x)<=BC_HEAD[dy+5])id=2;
int ey=dy-5;
int ax=abs(c.x);
bool right=c.x>0;
int lean=(k==2||((flags&BC_EAR)!=0&&right))?1:0;
if(ey>=0&&ey<=2&&ax>=2+ey+lean&&ax<=5+lean)id=2;
if((ey==0&&(ax==3+lean||ax==4+lean))||(ey==1&&ax==4+lean))id=4;
if(dy==1+look.y&&abs(c.x-look.x)==2)id=(flags&BC_BLINK)!=0?2:1;
if(ax<=1&&(dy==-1||dy==-2))id=(c.x==0&&dy==-1)?1:3;
return id;
}
int bigCatId(ivec2 c,int k,int tail,int hip,ivec2 look,int headUp,int flags){
int id=bigCatFill(c,k,tail,hip,look,headUp,flags);
if(id==0)return 0;
if(bigCatFill(c+ivec2(1,0),k,tail,hip,look,headUp,flags)==0||
bigCatFill(c-ivec2(1,0),k,tail,hip,look,headUp,flags)==0||
bigCatFill(c+ivec2(0,1),k,tail,hip,look,headUp,flags)==0||
bigCatFill(c-ivec2(0,1),k,tail,hip,look,headUp,flags)==0)return 1;
return id;
}
const vec3 BC_TEAL_D=vec3(.145,.31,.314);
const vec3 BC_TEAL_L=vec3(.22,.451,.455);
const vec3 BC_BLACK=vec3(.031,.027,.039);
const vec3 BC_FUR=vec3(.878,.522,.125);
const vec3 BC_CREAM=vec3(.976,.902,.729);
const vec3 BC_PINK=vec3(.949,.651,.702);
const float BC_CELL=7.;
const float BC_FLOOR=28.;
vec3 bigCatBackground(vec2 px,vec2 res){
float v=clamp((px.y/res.y-.12)/.76,0.,1.);
vec3 col=mix(BC_TEAL_D,BC_TEAL_L,step(bayer4(px),v));
if(px.y>=BC_FLOOR-3.&&px.y<BC_FLOOR-1.)col=BC_BLACK*.7;
return col;
}
vec3 bigCatColor(int id,vec3 col){
if(id==1)return BC_BLACK;
if(id==2)return BC_FUR;
if(id==3)return BC_CREAM;
if(id==4)return BC_PINK;
return col;
}

scenes.wake:
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord;
int ix=int(px.x);
int fy=146-int(px.y);
const vec3 pal[16]=vec3[16](
vec3(.004,.02,.03),
vec3(.01,.05,.06),
vec3(.016,.08,.1),
vec3(.03,.13,.15),
vec3(.05,.19,.21),
vec3(0.,0.,0.),
vec3(.85,.45,.1),
vec3(.92,.92,.88),
vec3(.008,.035,.045),
vec3(.04,.16,.18),
vec3(.07,.23,.25),
vec3(.7,.35,.08),
vec3(.95,.65,.25),
vec3(.75,.75,.72),
vec3(.02,.1,.12),
vec3(.06,.21,.23)
);
float e=easeOutCubic(clamp(uSceneProgress*5.,0.,1.));
int yOff=1-int(floor(e+.5));
float vis=e;
float depth=clamp(px.y/res.y,0.,1.);
vec3 col=(bayer4(px)<depth)?pal[3]:pal[2];
vec2 cell=floor(px/vec2(32.,24.));
float h=hash11(cell.x*7.31+cell.y*113.7+floor(uBar)*17.13);
vec2 sp=(cell+vec2(hash11(h+1.),hash11(h+2.)))*vec2(32.,24.);
if(h>.82&&length(px-(sp+vec2(.5)))<.6&&fract(uBar)>.5)col=pal[4];
bool show=bayer4(px)<vis;
if(show&&(fy==120||fy==121)&&ix>=38&&ix<=58)col=pal[1];
float tt=wrapTime(uSceneTime,.9375);
float sw=(.5-.5*cos(6.2831853*tt))*clamp(uSceneProgress*2.-.6,0.,1.);
int tj=39-ix;
if(show&&tj>=0&&tj<=9){
int lift=int(floor(sw*3.*(float(tj)/9.)+.5));
int dy=fy-(118+yOff-lift);
if(dy>=0&&dy<2)col=pal[6];
else if(dy==-1||dy==2)col=pal[5];
}
const uint CAT[16]=uint[16](
0u,3120u,3640u,4088u,4088u,4088u,4088u,8184u,
16380u,16380u,16382u,16382u,16382u,16382u,16380u,8184u
);
int lx=ix-40;
int r=fy-103-yOff;
if(show&&lx>=0&&lx<16&&r>=0&&r<15){
int m0=int((CAT[r]>>(15-lx))&1u);
if(m0==1){
int m1=(lx<15)?int((CAT[r]>>(14-lx))&1u):0;
int m2=(lx>0)?int((CAT[r]>>(16-lx))&1u):0;
int m3=(r<15)?int((CAT[r+1]>>(15-lx))&1u):0;
int m4=(r>0)?int((CAT[r-1]>>(15-lx))&1u):0;
int interior=m1*m2*m3*m4;
bool blink=fract(uSceneTime*.25)<.1;
if(lx==11&&r==4&&!blink){
col=pal[5];
}else if(interior==1){
if(lx>=9&&lx<=12&&r>=7&&r<=12)col=pal[7];
else col=pal[6];
}else{
col=pal[5];
}
}
}
vec2 uv=pixUV(fragCoord,res);
fragColor=vec4(retroFinalize(col,uv,fragCoord,pal,16),1.);
}

scenes.idle:
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord.xy;
int ft=int(floor(uSceneTime*12.));
bool blink=ft>=8&&ft<=9;
bool twitch=ft>=14&&ft<=17;
int tail=int(round(2.*sin(float(ft)*6.2831853/22.5)));
ivec2 g=ivec2(floor((px-vec2(160.,BC_FLOOR))/BC_CELL));
int flags=(twitch?BC_EAR:0)|(blink?BC_BLINK:0);
int id=bigCatId(g,0,tail,0,ivec2(0),0,flags);
vec3 col=bigCatColor(id,bigCatBackground(px,res));
fragColor=vec4(finalize(col,px/res),1.);
}

scenes.hunt:
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 px=fragCoord.xy;
int f=int(floor(uSceneTime*12.));
int k=0;
int tail=0;
int hip=0;
int headUp=0;
int flags=0;
ivec2 look=ivec2(-1,0);
float ox=160.;
float oy=BC_FLOOR;
const int WAG[4]=int[4](1,3,2,0);
if(f<6){
if(f>=3)flags|=BC_EAR;
}else if(f<8){
k=1;
}else if(f<24){
k=2;
tail=WAG[f%4];
if(f>=16)hip=((f/2)%2==0)?-1:1;
}else if(f<30){
float s=float(f-23)/7.;
k=2;
tail=3;
flags|=BC_AIR;
ox=floor(mix(160.,80.,s));
oy=BC_FLOOR+floor(36.*sin(3.14159265*s));
}else if(f<32){
k=2;
ox=80.;
tail=1;
look=ivec2(-1,1);
}else if(f<34){
k=1;
ox=80.;
look=ivec2(-1,1);
}else{
ox=80.;
headUp=1;
look=ivec2(-1,1);
tail=int(round(sin(float(f-34)*.6)));
}
ivec2 g=ivec2(floor((px-vec2(ox,oy))/BC_CELL));
int id=bigCatId(g,k,tail,hip,look,headUp,flags);
vec3 col=bigCatColor(id,bigCatBackground(px,res));
float mf=float(f);
vec2 moth=vec2(72.+floor(4.*sin(mf*.9)),58.+floor(5.*sin(mf*.55)));
if(f>=26){
float a=float(min(f,31)-25);
float b=float(max(f-31,0));
moth+=vec2(-8.*a-1.*b,9.*a+4.*b);
}
ivec2 q=ivec2(floor(px))-ivec2(moth);
bool wingsUp=(f%2)==0;
bool body=q.x>=0&&q.x<=1&&q.y>=0&&q.y<=1;
bool wing=(q.x==-2||q.x==-1||q.x==2||q.x==3)&&
(wingsUp?(q.y==1||q.y==2):(q.y==-1||q.y==0));
if(body||wing)col=BC_CREAM;
fragColor=vec4(finalize(col,px/res),1.);
}

