);
const int TB[8]=int[8](1,2,3,5,5,4,3,1);
bool catFur(ivec2 c,int earT,int tf){
if(c.y>=0&&c.y<=4&&c.x>=-5&&c.x<=4){
if(c.y==0&&(c.x<-3||c.x>2))return false;
return true;
}
if(c.y>=5&&c.y<=10&&c.x>=-4&&c.x<=3)return true;
int ey=c.y-earT;
if((c.x==-4&&ey==11)||(c.x==-3&&(ey==11||ey==12)))return true;
if((c.x==2&&ey==11)||(c.x==1&&(ey==11||ey==12)))return true;
int tb=TB[tf];
for(int i=0;i<5;i++){
int ty=tb+(i*i)/4;
if(c.x==4+i&&c.y==ty)return true;
}
return false;
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
vec2 res=iResolution.xy;
vec2 uv=pixUV(fragCoord,res);
vec2 px=fragCoord.xy;
float fy=res.y-1.-px.y;
float ox=160.;
float floorY=152.;
int fr=int(floor(uSceneTime*8.));
int earT=((fr%24)==13)?1:0;
bool blink=((fr%32)==15);
int tf=7-min(int(uSceneProgress*12.),7);
float sh=step(bayer4(fragCoord),uv.y*.45);
vec3 col=mix(PAL[4],PAL[5],sh);
if(fy>floorY+2.)col=PAL[7];
if(fy>=floorY&&fy<floorY+2.&&
px.x>ox-24.&&px.x<ox+38.){
col=PAL[6];
}
ivec2 c=ivec2(floor((px.x-ox)/4.),
floor((floorY-1.-fy)/4.));
if(c.x>=-13&&c.x<=12&&c.y>=0&&c.y<=13){
if(catFur(c,earT,tf)){
if((c.x==-2||c.x==1)&&c.y==8){
col=blink?PAL[1]:PAL[3];
}else if(c.x==0&&c.y==7){
col=PAL[2];
}else if(c.x>=-1&&c.x<=2&&c.y>=1&&c.y<=4){
col=PAL[2];
}else if(c.y<=4&&c.y>0&&((c.x+5)%3==0)){
col=PAL[3];
}else{
col=PAL[1];
}
}else{
ivec2 epx=ivec2(1,0),epy=ivec2(0,1);
if(catFur(c+epx,earT,tf)||catFur(c-epx,earT,tf)||
catFur(c+epy,earT,tf)||catFur(c-epy,earT,tf)){
col=PAL[0];
}
}
}
float f=easeOutCubic(clamp((uSceneProgress-.6667)*3.,0.,1.));
float dim=step(bayer4(fragCoord),1.-f);
col*=dim;
fragColor=vec4(retroFinalize(col,uv,fragCoord,PAL,8),1.);
}
